// CXC v0.2.40 CLI oracle. Usage: node record.mjs <read-only recall directory> <output>.
// Run with temporary HOME, CODEX_HOME, CRW_HOME and TMPDIR; the oracle is never edited.
import fs from 'node:fs';
import path from 'node:path';
const {main}=await import(path.resolve(process.argv[2], 'src/cli.ts'));
const root=fs.mkdtempSync(path.join(process.env.TMPDIR,'oracle-'));const home=path.join(root,'codex'),idx=path.join(root,'index.sqlite');fs.mkdirSync(home);process.env.CODEX_HOME=home;process.env.CODEXCLAW_HOME=path.join(root,'cxc');
const capture=argv=>{let stdout='',stderr='';const out=process.stdout.write,err=process.stderr.write;process.stdout.write=s=>(stdout+=s,true);process.stderr.write=s=>(stderr+=s,true);let code;try{code=main(argv);}finally{process.stdout.write=out;process.stderr.write=err;}const normalize=s=>s.replaceAll(home,'<HOME>').replaceAll(idx,'<INDEX>').replaceAll('cxc chat','crw recall chat').replaceAll('cxc memory','crw recall memory');return {argv:argv.map(normalize),code,stdout:normalize(stdout),stderr:normalize(stderr)};};
const rows=[];for(const argv of [
['chat','index','--home',home,'--index-path',idx,'--help'],['memory','search','--help'],['chat','index','--home',home,'--index-path',idx,'-h'],['chat','index','--home',home,'--index-path',idx,'help'],['chat','index','--home',home,'--index-path',idx,'/?'],
['memory','search','help','--home',home,'--no-chat','--json'],['chat','search','help','--home',home,'--scan','--json'],['memory','search','memory','--home',home,'--cwd-only','--no-chat','--json'],['memory','search','memory','--home',home,'--cwd-only=--no-chat','--json'],['chat','search','q','--home',home,'--cwd','--json','--scan'],['memory','search','q','--home','--json'],['chat','search','q','--home',home,'--cwd=--json','--scan'],['memory','search','q','--home=--json'],['memory','search','q','--home',home,'--cwd-only'],['chat','index','--home',home,'--index-path',idx,'--not-a-flag'],['memory','search','foo','--home',path.join(home,'missing'),'--no-chat','--json'],['chat','search'],['chat','search','q','--source','both'],['memory','status','--home',home,'--json'],['memory','requeue','--home',home,'--json'],['memory','status','--home',home,'--json=no','--unknown'],['memory','requeue','--home',home,'--limit=2tail','--json'],['chat','help'],['memory','help'],['nonsense'],['chat','search','--','--help']])rows.push(capture(argv));
fs.writeFileSync(process.argv[3],JSON.stringify(rows,null,2)+'\n');console.log('Recorded '+rows.length+' CLI cases; index created: '+fs.existsSync(idx));
